import{_ as t,o as r,c as o,ah as s}from"./chunks/framework.C-FRNfAJ.js";const g=JSON.parse('{"title":"Direction et reporting","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/direction/pilotage.md","filePath":"src/guide/direction/pilotage.md"}'),n={name:"guide/direction/pilotage.md"};function a(i,e,l,d,p,c){return r(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="direction-et-reporting" tabindex="-1">Direction et reporting <a class="header-anchor" href="#direction-et-reporting" aria-label="Permalink to &quot;Direction et reporting&quot;">​</a></h1><p>Deux pages de la rubrique <strong>Pilotage</strong> donnent la vue d&#39;ensemble de l&#39;activité, <strong>en lecture seule</strong> : la <strong>Vue Direction</strong> et le <strong>Reporting</strong>. Elles reposent sur les mêmes périodes, les mêmes filtres et les mêmes définitions.</p><table tabindex="0"><thead><tr><th>Page</th><th>Pour qui</th><th>Particularité</th></tr></thead><tbody><tr><td><strong>Vue Direction</strong></td><td>Direction, Administrateur</td><td>Montre le versé et la marge</td></tr><tr><td><strong>Reporting</strong></td><td>Coordinateur pédagogique, Administrateur</td><td>Sans versé ni marge ; avec l&#39;assiduité et les notes ; export CSV</td></tr></tbody></table><h2 id="choisir-ce-qu-on-regarde" tabindex="-1">Choisir ce qu&#39;on regarde <a class="header-anchor" href="#choisir-ce-qu-on-regarde" aria-label="Permalink to &quot;Choisir ce qu&#39;on regarde&quot;">​</a></h2><p>Les deux pages portent sur les <strong>cohortes qui démarrent dans l&#39;année choisie</strong> (l&#39;année en cours par défaut). Filtrez ensuite par <strong>programme</strong> et par <strong>promotion</strong>. Une cohorte reportée ou annulée ne compte ni dans les places, ni dans les zones.</p><h2 id="la-vue-direction" tabindex="-1">La Vue Direction <a class="header-anchor" href="#la-vue-direction" aria-label="Permalink to &quot;La Vue Direction&quot;">​</a></h2><p><strong>Formation :</strong></p><ul><li>les cohortes <strong>par statut</strong> ;</li><li>les <strong>zones d&#39;effectif</strong> (Fragile, Viable, Confortable), figées au démarrage pour les cohortes commencées, actuelles pour les cohortes à venir ;</li><li>le <strong>taux de remplissage</strong> : apprenants sur places.</li></ul><p><strong>Taux de réussite.</strong> Il porte sur les cohortes <strong>terminées</strong> : les apprenants certifiés rapportés aux apprenants sortis. Est « sorti » un apprenant qui a terminé une cohorte achevée, certifié ou non ; <strong>un abandon après signature compte comme un échec</strong>.</p><p><strong>Finance :</strong></p><table tabindex="0"><thead><tr><th>Indicateur</th><th>Définition</th></tr></thead><tbody><tr><td>Facturé</td><td>Net des avoirs d&#39;annulation</td></tr><tr><td>Encaissé</td><td>Net des remboursements</td></tr><tr><td>Reste à encaisser</td><td>Dont le montant en retard</td></tr><tr><td>Versé</td><td>Rémunérations des formateurs, coachs et jurys</td></tr><tr><td>Marge brute</td><td>Encaissé moins versé</td></tr></tbody></table><p>Un détail <strong>par programme</strong> et <strong>par promotion</strong> accompagne ces chiffres.</p><p><strong>Participations L&#39;Éclosion.</strong> Le portefeuille liste les participations validées par le comité d&#39;investissement, tous cycles confondus : projet, cycle, type, part et date de validation.</p><h2 id="le-reporting" tabindex="-1">Le Reporting <a class="header-anchor" href="#le-reporting" aria-label="Permalink to &quot;Le Reporting&quot;">​</a></h2><p>Le Reporting reprend le remplissage, la réussite (avec le nombre d&#39;attestations partielles), le facturé, l&#39;encaissé et le reste dû, et ajoute :</p><ul><li>l&#39;<strong>assiduité</strong> : le temps de présence des apprenants confirmés, présents ou en retard, rapporté à la durée des séances saisies pour eux ;</li><li>la <strong>moyenne générale</strong> : la moyenne des moyennes pondérées des apprenants qui ont au moins un bloc noté, sur 20.</li></ul><p>Le détail est <strong>par programme</strong>, <strong>par promotion</strong>, puis <strong>une ligne par cohorte</strong>, qui mène à la fiche de la cohorte.</p><p><strong>Exporter en CSV</strong> produit la liste des cohortes de la sélection (séparateur point-virgule, UTF-8, dans la langue de l&#39;utilisateur).</p><h2 id="le-comite-d-investissement" tabindex="-1">Le comité d&#39;investissement <a class="header-anchor" href="#le-comite-d-investissement" aria-label="Permalink to &quot;Le comité d&#39;investissement&quot;">​</a></h2><p>La Direction siège aussi au <strong>comité d&#39;investissement</strong> de L&#39;Éclosion, avec le Chargé d&#39;incubation et le Coordinateur pédagogique : voir <a href="./../activites/eclosion.html#la-participation-et-le-comite-d-investissement">L&#39;Éclosion</a>. C&#39;est le seul endroit où la Direction agit, le reste de ses pages étant en lecture seule.</p>',20)])])}const m=t(n,[["render",a]]);export{g as __pageData,m as default};
